mapper.update:
UPDATE servers
SET
    ssh_host_key_algorithm = #{hostKeyAlgorithm},
    ssh_host_key_fingerprint = #{newFingerprint},
    ssh_host_key_verified_by = #{operatorId},
    ssh_host_key_verified_at = CURRENT_TIMESTAMP(6)
WHERE id = #{serverId}
  AND deleted = 0
  AND ssh_host = #{expectedSshHost}
  AND ssh_port = #{expectedSshPort}
  AND ssh_host_key_fingerprint <=> #{previousFingerprint}
